type vertex={x:float;y:float;depth:float;color:int32;u:float;v:float} type cull=Cull_none|Back|Front type texture={surface:Surface.t;filter:Image.filter} type clip={x:int;y:int;width:int;height:int}
let ch c n=Int32.(to_int(logand(shift_right_logical c n)0xffl))
let rgba r g b a=Int32.(logor(shift_left(of_int r)24)(logor(shift_left(of_int g)16)(logor(shift_left(of_int b)8)(of_int a))))
let sample t u v=let w=Surface.width t.surface and h=Surface.height t.surface in let get x y=match Surface.get_rgba t.surface~x:(max 0(min(w-1)x))~y:(max 0(min(h-1)y))with Ok c->c|_->0xffffffffl in match t.filter with Image.Nearest->get(int_of_float(u*.float w))(int_of_float(v*.float h))|Bilinear->let fx=u*.float w-.0.5 and fy=v*.float h-.0.5 in let x=int_of_float(floor fx)and y=int_of_float(floor fy)in let wx=fx-.floor fx and wy=fy-.floor fy and p00=get x y and p10=get(x+1)y and p01=get x(y+1)and p11=get(x+1)(y+1)in let f n=int_of_float(((1.-.wx)*.(1.-.wy)*.float(ch p00 n)+.wx*.(1.-.wy)*.float(ch p10 n)+.(1.-.wx)*.wy*.float(ch p01 n)+.wx*.wy*.float(ch p11 n))+.0.5)in rgba(f 24)(f 16)(f 8)(f 0)
let edge (a:vertex) (b:vertex) x y=(x-.a.x)*.(b.y-.a.y)-.(y-.a.y)*.(b.x-.a.x)
let top (a:vertex) (b:vertex)=a.y<b.y||(a.y=b.y&&a.x>b.x)
let draw ~color ~depth ~depth_state ~blend ~cull ~clip ~texture (a:vertex) (b:vertex) (c:vertex)=let area=edge a b c.x c.y in let rejected=area=0.||match cull with Back->area<=0.|Front->area>=0.|Cull_none->false in if not rejected then let a,b,area=if area<0. then b,a,-.area else a,b,area in let xmin=max clip.x(max 0(int_of_float(floor(min a.x(min b.x c.x)))))and ymin=max clip.y(max 0(int_of_float(floor(min a.y(min b.y c.y)))))and xmax=min(clip.x+clip.width-1)(min(Surface.width color-1)(int_of_float(ceil(max a.x(max b.x c.x)))))and ymax=min(clip.y+clip.height-1)(min(Surface.height color-1)(int_of_float(ceil(max a.y(max b.y c.y)))))in for y=ymin to ymax do for x=xmin to xmax do let px=float x+.0.5 and py=float y+.0.5 in let w0=edge b c px py and w1=edge c a px py and w2=edge a b px py in if (w0>0.||w0=0.&&top b c)&&(w1>0.||w1=0.&&top c a)&&(w2>0.||w2=0.&&top a b)then let w0=w0/.area and w1=w1/.area and w2=w2/.area in let z=w0*.a.depth+.w1*.b.depth+.w2*.c.depth in let pass=match depth with None->true|Some d->(match Depth_stencil.test_and_update d depth_state~x~y~depth:z with Ok p->p|_->false)in if pass then let f n=int_of_float(w0*.float(ch a.color n)+.w1*.float(ch b.color n)+.w2*.float(ch c.color n)+.0.5)in let base=rgba(f 24)(f 16)(f 8)(f 0)in let out=match texture with None->base|Some t->let q=sample t(w0*.a.u+.w1*.b.u+.w2*.c.u)(w0*.a.v+.w1*.b.v+.w2*.c.v)in rgba(ch base 24*ch q 24/255)(ch base 16*ch q 16/255)(ch base 8*ch q 8/255)(ch base 0*ch q 0/255)in Composite.pixel color~blend~x~y out done done
